INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-01-01-kenya-etims-return-validation', '2026-01-01', '2026-01', 'From 1 January 2026, Kenya''s KRA validates the income and expenses declared in income tax returns against eTIMS invoice data, withholding tax records and customs imports -- taking the higher of declared vs eTIMS income and the lower of declared vs eTIMS expenses. Expenses without a compliant e-invoice face administrative disallowance at filing time.', '<h3>🇰🇪 Kenya starts cross-checking every tax return against eTIMS</h3>
<p>Kenya''s e-invoicing regime has never gated invoice validity the way clearance systems do -- instead it follows the money. Since January 2024, business expenses without an eTIMS-generated electronic tax invoice have been non-deductible for income tax. From 1 January 2026, per a KRA public notice of 10 November 2025, that rule is enforced automatically: declared income and expenses in income tax returns are validated against TIMS/eTIMS invoice data, withholding tax records and customs import records.</p>
<p>In practice, KRA takes the higher of declared income versus eTIMS sales data, and the lower of declared expenses versus eTIMS purchase data -- so unsupported amounts surface at filing time, not in a later audit. With over 508,000 taxpayers onboarded on eTIMS (September 2025) and a target of one million, the message to Kenyan businesses is that reconciliation against eTIMS data is now a year-round discipline, and a supplier''s paper invoice is a real cost.</p>', 'https://www.kra.go.ke/news-center/public-notices/2323-validation-of-income-and-expenses-in-the-income-tax-returns', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2026-01-01-kenya-etims-return-validation', id FROM countries WHERE code = 'KE';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-kenya-etims-return-validation', 'en', 'Kenya starts cross-checking every tax return against eTIMS', 'From 1 January 2026, Kenya''s KRA validates the income and expenses declared in income tax returns against eTIMS invoice data, withholding tax records and customs imports -- taking the higher of declared vs eTIMS income and the lower of declared vs eTIMS expenses. Expenses without a compliant e-invoice face administrative disallowance at filing time.', '<h3>🇰🇪 Kenya starts cross-checking every tax return against eTIMS</h3>
<p>Kenya''s e-invoicing regime has never gated invoice validity the way clearance systems do -- instead it follows the money. Since January 2024, business expenses without an eTIMS-generated electronic tax invoice have been non-deductible for income tax. From 1 January 2026, per a KRA public notice of 10 November 2025, that rule is enforced automatically: declared income and expenses in income tax returns are validated against TIMS/eTIMS invoice data, withholding tax records and customs import records.</p>
<p>In practice, KRA takes the higher of declared income versus eTIMS sales data, and the lower of declared expenses versus eTIMS purchase data -- so unsupported amounts surface at filing time, not in a later audit. With over 508,000 taxpayers onboarded on eTIMS (September 2025) and a target of one million, the message to Kenyan businesses is that reconciliation against eTIMS data is now a year-round discipline, and a supplier''s paper invoice is a real cost.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-kenya-etims-return-validation', 'es', 'Kenia empieza a cotejar cada declaración fiscal con eTIMS', 'Desde el 1 de enero de 2026, la KRA de Kenia valida los ingresos y gastos declarados en las declaraciones del impuesto sobre la renta contra los datos de facturas de eTIMS, los registros de retenciones y las importaciones aduaneras -- tomando el mayor entre los ingresos declarados y los de eTIMS, y el menor entre los gastos declarados y los de eTIMS. Los gastos sin una factura electrónica conforme se enfrentan a una denegación administrativa al presentar la declaración.', '<h3>🇰🇪 Kenia empieza a cotejar cada declaración fiscal con eTIMS</h3>
<p>El régimen de facturación electrónica de Kenia nunca ha condicionado la validez de la factura como lo hacen los sistemas de clearance: en su lugar, sigue el dinero. Desde enero de 2024, los gastos empresariales sin una factura fiscal electrónica generada por eTIMS no son deducibles en el impuesto sobre la renta. Desde el 1 de enero de 2026, según un aviso público de la KRA del 10 de noviembre de 2025, esa regla se aplica automáticamente: los ingresos y gastos declarados se validan contra los datos de facturas de TIMS/eTIMS, los registros de retenciones y los registros de importación aduanera.</p>
<p>En la práctica, la KRA toma el mayor entre los ingresos declarados y los datos de ventas de eTIMS, y el menor entre los gastos declarados y los datos de compras de eTIMS -- de modo que los importes sin respaldo afloran al presentar la declaración, no en una auditoría posterior. Con más de 508.000 contribuyentes incorporados a eTIMS (septiembre de 2025) y una meta de un millón, el mensaje para las empresas kenianas es que la conciliación contra los datos de eTIMS es ahora una disciplina de todo el año, y la factura en papel de un proveedor tiene un coste real.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-kenya-etims-return-validation', 'de', 'Kenia gleicht jetzt jede Steuererklärung mit eTIMS ab', 'Seit dem 1. Januar 2026 validiert Kenias KRA die in Einkommensteuererklärungen angegebenen Einnahmen und Ausgaben gegen eTIMS-Rechnungsdaten, Quellensteuerdaten und Zollimporte -- angesetzt wird der höhere Wert bei den Einnahmen und der niedrigere bei den Ausgaben. Ausgaben ohne konforme E-Rechnung werden bereits bei der Abgabe administrativ aberkannt.', '<h3>🇰🇪 Kenia gleicht jetzt jede Steuererklärung mit eTIMS ab</h3>
<p>Kenias E-Invoicing-Regime hat die Rechnungsgültigkeit nie so verriegelt wie Clearance-Systeme -- es folgt stattdessen dem Geld. Seit Januar 2024 sind Betriebsausgaben ohne eine über eTIMS erzeugte elektronische Steuerrechnung bei der Einkommensteuer nicht abzugsfähig. Seit dem 1. Januar 2026 wird diese Regel laut einer öffentlichen KRA-Bekanntmachung vom 10. November 2025 automatisch durchgesetzt: Die erklärten Einnahmen und Ausgaben werden gegen TIMS/eTIMS-Rechnungsdaten, Quellensteuerdaten und Zollimportdaten validiert.</p>
<p>In der Praxis setzt die KRA bei den Einnahmen den höheren Wert (erklärt vs. eTIMS-Verkaufsdaten) und bei den Ausgaben den niedrigeren Wert (erklärt vs. eTIMS-Einkaufsdaten) an -- unbelegte Beträge fallen also schon bei der Abgabe auf, nicht erst in einer späteren Prüfung. Mit über 508.000 auf eTIMS registrierten Steuerpflichtigen (September 2025) und dem Ziel von einer Million ist die Botschaft an Kenias Unternehmen klar: Der Abgleich mit eTIMS-Daten ist jetzt eine ganzjährige Disziplin, und die Papierrechnung eines Lieferanten kostet echtes Geld.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-01-01-kenya-etims-return-validation', 'fr', 'Le Kenya croise désormais chaque déclaration fiscale avec eTIMS', 'Depuis le 1er janvier 2026, la KRA du Kenya valide les revenus et les dépenses déclarés dans les déclarations d''impôt sur le revenu par rapport aux données de facturation eTIMS, aux retenues à la source et aux importations douanières -- en retenant le montant le plus élevé pour les revenus et le plus faible pour les dépenses. Les dépenses sans facture électronique conforme font l''objet d''un rejet administratif dès le dépôt.', '<h3>🇰🇪 Le Kenya croise désormais chaque déclaration fiscale avec eTIMS</h3>
<p>Le régime de facturation électronique du Kenya n''a jamais conditionné la validité des factures comme le font les systèmes de clearance -- il suit plutôt l''argent. Depuis janvier 2024, les dépenses professionnelles sans facture fiscale électronique générée via eTIMS ne sont pas déductibles de l''impôt sur le revenu. Depuis le 1er janvier 2026, selon un avis public de la KRA du 10 novembre 2025, cette règle est appliquée automatiquement : les revenus et dépenses déclarés sont validés par rapport aux données de facturation TIMS/eTIMS, aux retenues à la source et aux registres d''importation douanière.</p>
<p>En pratique, la KRA retient le montant le plus élevé entre les revenus déclarés et les données de ventes eTIMS, et le plus faible entre les dépenses déclarées et les données d''achats eTIMS -- les montants non justifiés apparaissent donc dès le dépôt, et non lors d''un contrôle ultérieur. Avec plus de 508 000 contribuables intégrés à eTIMS (septembre 2025) et un objectif d''un million, le message aux entreprises kenyanes est clair : le rapprochement avec les données eTIMS est désormais une discipline permanente, et la facture papier d''un fournisseur a un coût réel.</p>');

INSERT OR IGNORE INTO stories (id, date, month, summary_en, html_en, source_url, published) VALUES ('2026-07-31-nigeria-enforcement-begins', '2026-07-31', '2026-07', 'Nigeria''s e-invoicing grace period is over: the NRS set 31 July 2026 as the hard final deadline for large taxpayers (>= NGN 5bn turnover) to complete onboarding and live IRN transmission through the Merchant Buyer Solution, with enforcement from August. Just a year after its August 2025 go-live, Nigeria also became the first African country on OpenPeppol''s Peppol Authority list.', '<h3>🇳🇬 Nigeria''s e-invoicing enforcement begins -- a year after Africa''s fastest rollout</h3>
<p>Nigeria compressed into two years what most countries spread over five: the Merchant Buyer Solution (FIRSMBS) was announced in late 2024, unveiled in April 2025, and live by 1 August 2025 -- with MTN Nigeria, Huawei and IHS transmitting the country''s first cleared e-invoices, each validated before delivery and stamped with an Invoice Reference Number and cryptographic seal. Eight weeks later, Nigeria became the first African country on OpenPeppol''s Peppol Authority list.</p>
<p>The Nigeria Revenue Service (as FIRS became on 1 January 2026, when the reform acts also made the penalties statutory) has now ended the grace period: 31 July 2026 is the hard deadline for the roughly 5,000 large taxpayers to be transmitting live, with compliance monitoring and enforcement from August -- a NGN 200,000 penalty plus 100% of the tax due for invoices processed outside the system, and buyers losing the input-VAT credit on non-compliant invoices. Medium taxpayers (NGN 1-5bn) joined on 1 July 2026, and businesses under NGN 1bn follow from July 2027.</p>', 'https://www.thisdaylive.com/2026/07/20/nrs-issues-large-taxpayers-july-31-deadline-for-e-invoicing-compliance/', 1);
INSERT OR IGNORE INTO story_countries (story_id, country_id) SELECT '2026-07-31-nigeria-enforcement-begins', id FROM countries WHERE code = 'NG';
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-31-nigeria-enforcement-begins', 'en', 'Nigeria''s e-invoicing enforcement begins -- a year after Africa''s fastest rollout', 'Nigeria''s e-invoicing grace period is over: the NRS set 31 July 2026 as the hard final deadline for large taxpayers (>= NGN 5bn turnover) to complete onboarding and live IRN transmission through the Merchant Buyer Solution, with enforcement from August. Just a year after its August 2025 go-live, Nigeria also became the first African country on OpenPeppol''s Peppol Authority list.', '<h3>🇳🇬 Nigeria''s e-invoicing enforcement begins -- a year after Africa''s fastest rollout</h3>
<p>Nigeria compressed into two years what most countries spread over five: the Merchant Buyer Solution (FIRSMBS) was announced in late 2024, unveiled in April 2025, and live by 1 August 2025 -- with MTN Nigeria, Huawei and IHS transmitting the country''s first cleared e-invoices, each validated before delivery and stamped with an Invoice Reference Number and cryptographic seal. Eight weeks later, Nigeria became the first African country on OpenPeppol''s Peppol Authority list.</p>
<p>The Nigeria Revenue Service (as FIRS became on 1 January 2026, when the reform acts also made the penalties statutory) has now ended the grace period: 31 July 2026 is the hard deadline for the roughly 5,000 large taxpayers to be transmitting live, with compliance monitoring and enforcement from August -- a NGN 200,000 penalty plus 100% of the tax due for invoices processed outside the system, and buyers losing the input-VAT credit on non-compliant invoices. Medium taxpayers (NGN 1-5bn) joined on 1 July 2026, and businesses under NGN 1bn follow from July 2027.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-31-nigeria-enforcement-begins', 'es', 'Comienza la ejecución del mandato nigeriano -- un año después del despliegue más rápido de África', 'Se acabó el período de gracia de la facturación electrónica en Nigeria: el NRS fijó el 31 de julio de 2026 como fecha límite definitiva para que los grandes contribuyentes (facturación >= NGN 5.000 millones) completen su incorporación y la transmisión en vivo de IRN a través del Merchant Buyer Solution, con ejecución desde agosto. Apenas un año después de su puesta en marcha en agosto de 2025, Nigeria se convirtió además en el primer país africano en la lista de Autoridades Peppol de OpenPeppol.', '<h3>🇳🇬 Comienza la ejecución del mandato nigeriano -- un año después del despliegue más rápido de África</h3>
<p>Nigeria comprimió en dos años lo que la mayoría de los países reparte en cinco: el Merchant Buyer Solution (FIRSMBS) se anunció a finales de 2024, se presentó en abril de 2025 y estaba en vivo el 1 de agosto de 2025 -- con MTN Nigeria, Huawei e IHS transmitiendo las primeras facturas electrónicas validadas del país, cada una verificada antes de la entrega y sellada con un Invoice Reference Number (IRN) y un sello criptográfico. Ocho semanas después, Nigeria se convirtió en el primer país africano en la lista de Autoridades Peppol de OpenPeppol.</p>
<p>El Nigeria Revenue Service (en que se convirtió el FIRS el 1 de enero de 2026, cuando las leyes de reforma también dieron rango legal a las sanciones) ha puesto fin al período de gracia: el 31 de julio de 2026 es la fecha límite definitiva para que los aproximadamente 5.000 grandes contribuyentes transmitan en vivo, con supervisión y ejecución desde agosto -- una sanción de NGN 200,000 más el 100% del impuesto adeudado por las facturas procesadas fuera del sistema, y la pérdida del crédito de IVA soportado para los compradores con facturas no conformes. Los contribuyentes medianos (NGN 1.000-5.000 millones) se incorporaron el 1 de julio de 2026, y las empresas por debajo de NGN 1.000 millones seguirán desde julio de 2027.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-31-nigeria-enforcement-begins', 'de', 'Nigerias E-Invoicing-Durchsetzung beginnt -- ein Jahr nach Afrikas schnellstem Rollout', 'Nigerias Schonfrist ist vorbei: Der NRS setzte den 31. Juli 2026 als endgültige Frist, bis zu der große Steuerpflichtige (Umsatz >= NGN 5 Mrd.) Onboarding und Live-IRN-Übermittlung über die Merchant Buyer Solution abgeschlossen haben müssen -- mit Durchsetzung ab August. Nur ein Jahr nach dem Go-live im August 2025 wurde Nigeria zudem das erste afrikanische Land auf OpenPeppols Liste der Peppol-Behörden.', '<h3>🇳🇬 Nigerias E-Invoicing-Durchsetzung beginnt -- ein Jahr nach Afrikas schnellstem Rollout</h3>
<p>Nigeria hat in zwei Jahre gepresst, was die meisten Länder über fünf verteilen: Die Merchant Buyer Solution (FIRSMBS) wurde Ende 2024 angekündigt, im April 2025 vorgestellt und war am 1. August 2025 live -- MTN Nigeria, Huawei und IHS übermittelten die ersten freigegebenen E-Rechnungen des Landes, jede vor Zustellung validiert und mit Invoice Reference Number (IRN) und kryptografischem Siegel versehen. Acht Wochen später wurde Nigeria das erste afrikanische Land auf OpenPeppols Liste der Peppol-Behörden.</p>
<p>Der Nigeria Revenue Service (zu dem der FIRS am 1. Januar 2026 wurde, als die Reformgesetze auch die Sanktionen gesetzlich verankerten) hat die Schonfrist nun beendet: Der 31. Juli 2026 ist die harte Frist, bis zu der die rund 5.000 großen Steuerpflichtigen live übermitteln müssen, mit Compliance-Überwachung und Durchsetzung ab August -- NGN 200.000 Strafe plus 100% der geschuldeten Steuer für außerhalb des Systems verarbeitete Rechnungen, und Käufer verlieren den Vorsteuerabzug bei nicht konformen Rechnungen. Mittlere Steuerpflichtige (NGN 1-5 Mrd.) folgten am 1. Juli 2026, Unternehmen unter NGN 1 Mrd. ab Juli 2027.</p>');
INSERT OR IGNORE INTO story_translations (story_id, lang, title, summary, html) VALUES ('2026-07-31-nigeria-enforcement-begins', 'fr', 'La mise en application du mandat nigérian commence -- un an après le déploiement le plus rapide d''Afrique', 'La période de grâce est terminée au Nigéria : le NRS a fixé au 31 juillet 2026 la date limite définitive pour que les grands contribuables (chiffre d''affaires >= 5 milliards de NGN) achèvent leur intégration et la transmission en direct des IRN via le Merchant Buyer Solution, avec mise en application dès août. Un an à peine après son lancement en août 2025, le Nigéria est aussi devenu le premier pays africain inscrit sur la liste des Autorités Peppol d''OpenPeppol.', '<h3>🇳🇬 La mise en application du mandat nigérian commence -- un an après le déploiement le plus rapide d''Afrique</h3>
<p>Le Nigéria a comprimé en deux ans ce que la plupart des pays étalent sur cinq : le Merchant Buyer Solution (FIRSMBS) a été annoncé fin 2024, dévoilé en avril 2025 et mis en service le 1er août 2025 -- MTN Nigeria, Huawei et IHS transmettant les premières factures électroniques validées du pays, chacune contrôlée avant livraison et frappée d''un Invoice Reference Number (IRN) et d''un sceau cryptographique. Huit semaines plus tard, le Nigéria devenait le premier pays africain inscrit sur la liste des Autorités Peppol d''OpenPeppol.</p>
<p>Le Nigeria Revenue Service (nouveau nom du FIRS depuis le 1er janvier 2026, date à laquelle les lois de réforme ont aussi donné force légale aux sanctions) a mis fin à la période de grâce : le 31 juillet 2026 est la date limite ferme pour que les quelque 5 000 grands contribuables transmettent en direct, avec surveillance et mise en application dès août -- une amende de 200 000 NGN plus 100 % de la taxe due pour les factures traitées hors du système, et la perte du crédit de TVA déductible pour les acheteurs sur les factures non conformes. Les contribuables moyens (1 à 5 milliards de NGN) ont suivi le 1er juillet 2026, et les entreprises sous 1 milliard de NGN suivront à partir de juillet 2027.</p>');
